40: export interface JobExecutorDependencies {
41:   store?: JobRunStore;
42:   ask?: typeof askWorker;
43:   shadow?: typeof startShadowRun;
44:   worker?: WorkerChatOpts;
45:   /** Captured synchronously at the start of each book-based preparation.
46:    * The provider reads the authoritative Desk, never its cached projection. */
47:   readBookSnapshot?: () => DeskSnapshot;
48:   /** Test/local-office workroom override. Never supplied by a model. */
49:   workroom?: string;
50:   /** Trusted, reviewed pack instructions resolved after this run holds its job.
51:    * No model-supplied path or authority; pack upgrades reject active jobs. */
52:   instructionContext?: (recipeId: string) => Promise<string>;
53:   /** Assigned company case preparation never inherits the private book, files,
54:    * accounts adapters or ordinary profile worker. The authority supplies the
55:    * selected source and checks every provider/result boundary. */
56:   department?: { source(): Promise<CompanyExecutionSource>; check(): Promise<void>; ask: typeof askWorker };
57: }
